/*
  server.js — ISO 9001 app server (Q-Ki-ALL-001-Rec-005) — เวอร์ชันเว็บสาธารณะ
  ไฟล์เดียวจบ (ฝังแอปไว้ในไฟล์นี้แล้ว) เก็บข้อมูลบน MongoDB Atlas (ฟรีถาวร) แทนไฟล์ในเครื่อง
  เพราะ hosting ฟรีส่วนใหญ่ (เช่น Render) ไม่มีดิสก์ถาวร ข้อมูลในไฟล์จะหายทุกครั้งที่รีสตาร์ท

  วิธีใช้งาน:
   1) ตั้งค่า environment variable ชื่อ MONGODB_URI ให้เป็น connection string จาก MongoDB Atlas
   2) รัน: npm install (ติดตั้ง mongodb driver ครั้งเดียว)
   3) รัน: node server.js
   4) เข้าใช้งานผ่าน URL ที่ hosting ให้มา (เช่น https://your-app.onrender.com)
*/

const http = require('http');
const crypto = require('crypto');
const { MongoClient } = require('mongodb');

const PORT = process.env.PORT || 3000;
const MONGODB_URI = process.env.MONGODB_URI;

let dbCollection = null;
let dbUsers = null;
let dbLoginLogs = null;

async function connectDB() {
  if (!MONGODB_URI) {
    console.error('[FATAL] ไม่ได้ตั้งค่า MONGODB_URI — แอปจะเปิดหน้าเว็บได้ แต่บันทึก/โหลดข้อมูลไม่ได้');
    return;
  }
  try {
    const client = new MongoClient(MONGODB_URI);
    await client.connect();
    const db = client.db('iso9001');
    dbCollection = db.collection('storage');
    await dbCollection.createIndex({ key: 1 }, { unique: true });
    dbUsers = db.collection('users');
    await dbUsers.createIndex({ username: 1 }, { unique: true });
    dbLoginLogs = db.collection('loginlogs');
    console.log('เชื่อมต่อฐานข้อมูล MongoDB Atlas สำเร็จ');
  } catch (e) {
    console.error('[ERROR] เชื่อมต่อ MongoDB Atlas ไม่สำเร็จ:', e.message);
  }
}

/* ---------- ระบบรหัสผ่าน (hash ด้วย scrypt ในตัว Node ไม่ต้องติดตั้ง library เพิ่ม) ---------- */
function hashPassword(password) {
  const salt = crypto.randomBytes(16).toString('hex');
  const hash = crypto.scryptSync(password, salt, 64).toString('hex');
  return salt + ':' + hash;
}
function verifyPassword(password, stored) {
  const [salt, hash] = String(stored || '').split(':');
  if (!salt || !hash) return false;
  const check = crypto.scryptSync(password, salt, 64).toString('hex');
  try {
    return crypto.timingSafeEqual(Buffer.from(hash, 'hex'), Buffer.from(check, 'hex'));
  } catch (e) {
    return false;
  }
}

/* ---------- ระบบ session ง่ายๆ เก็บใน memory (พอเซิร์ฟเวอร์รีสตาร์ท ต้อง login ใหม่) ---------- */
const sessions = new Map();
function parseCookies(req) {
  const header = req.headers.cookie;
  const out = {};
  if (!header) return out;
  header.split(';').forEach((part) => {
    const idx = part.indexOf('=');
    if (idx === -1) return;
    const k = part.slice(0, idx).trim();
    const v = part.slice(idx + 1).trim();
    out[k] = decodeURIComponent(v);
  });
  return out;
}
function getSession(req) {
  const cookies = parseCookies(req);
  const sid = cookies.sid;
  if (!sid) return null;
  return sessions.get(sid) || null;
}
function setSessionCookie(res, sid) {
  res.setHeader('Set-Cookie', 'sid=' + sid + '; HttpOnly; Path=/; Max-Age=2592000; SameSite=Lax');
}
function clearSessionCookie(res) {
  res.setHeader('Set-Cookie', 'sid=; HttpOnly; Path=/; Max-Age=0; SameSite=Lax');
}
function getClientIp(req) {
  const fwd = req.headers['x-forwarded-for'];
  if (fwd) return String(fwd).split(',')[0].trim();
  return req.socket.remoteAddress || '';
}

// ---------- แอป HTML ฝังอยู่ในไฟล์นี้เลย (base64) ----------
const APP_HTML_BASE64 = "";
const APP_HTML = Buffer.from(APP_HTML_BASE64, 'base64').toString('utf8');

function sendJSON(res, status, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(body),
  });
  res.end(body);
}

const server = http.createServer((req, res) => {
  (async () => {
    let url;
    try {
      url = new URL(req.url, 'http://' + req.headers.host);
    } catch (e) {
      res.writeHead(400); res.end('Bad request'); return;
    }

    // ---- API: สถานะระบบยืนยันตัวตน (มีผู้ใช้ตั้งไว้แล้วหรือยัง) ----
    if (req.method === 'GET' && url.pathname === '/api/auth/status') {
      if (!dbUsers) return sendJSON(res, 500, { error: 'database not connected' });
      try {
        const count = await dbUsers.countDocuments();
        return sendJSON(res, 200, { hasUsers: count > 0 });
      } catch (e) {
        return sendJSON(res, 500, { error: 'database error', detail: e.message });
      }
    }

    // ---- API: ตั้งค่าครั้งแรก (คนแรกที่ตั้งรหัส = แอดมิน) ----
    if (req.method === 'POST' && url.pathname === '/api/auth/setup') {
      if (!dbUsers) return sendJSON(res, 500, { error: 'database not connected' });
      let body = '';
      req.on('data', (chunk) => { body += chunk; });
      req.on('end', async () => {
        try {
          const count = await dbUsers.countDocuments();
          if (count > 0) return sendJSON(res, 403, { error: 'ระบบตั้งค่าแอดมินไปแล้ว กรุณาเข้าสู่ระบบแทน' });
          const data = JSON.parse(body);
          const username = String(data.username || '').trim();
          const password = String(data.password || '');
          if (!username || !password) return sendJSON(res, 400, { error: 'กรุณากรอกชื่อผู้ใช้และรหัสผ่าน' });
          if (password.length < 6) return sendJSON(res, 400, { error: 'รหัสผ่านต้องมีอย่างน้อย 6 ตัวอักษร' });
          const passwordHash = hashPassword(password);
          await dbUsers.insertOne({ username, passwordHash, role: 'admin', createdAt: new Date() });
          const sid = crypto.randomBytes(24).toString('hex');
          sessions.set(sid, { username, role: 'admin' });
          setSessionCookie(res, sid);
          if (dbLoginLogs) dbLoginLogs.insertOne({ username, time: new Date(), success: true, ip: getClientIp(req), note: 'initial setup' }).catch(() => {});
          return sendJSON(res, 200, { ok: true, username, role: 'admin' });
        } catch (e) {
          if (e && e.code === 11000) return sendJSON(res, 403, { error: 'ระบบตั้งค่าแอดมินไปแล้ว กรุณาเข้าสู่ระบบแทน' });
          return sendJSON(res, 400, { error: 'invalid body', detail: e.message });
        }
      });
      return;
    }

    // ---- API: เข้าสู่ระบบ ----
    if (req.method === 'POST' && url.pathname === '/api/auth/login') {
      if (!dbUsers) return sendJSON(res, 500, { error: 'database not connected' });
      let body = '';
      req.on('data', (chunk) => { body += chunk; });
      req.on('end', async () => {
        let username = '';
        try {
          const data = JSON.parse(body);
          username = String(data.username || '').trim();
          const password = String(data.password || '');
          const user = await dbUsers.findOne({ username });
          const ok = user && verifyPassword(password, user.passwordHash);
          if (dbLoginLogs) dbLoginLogs.insertOne({ username, time: new Date(), success: !!ok, ip: getClientIp(req) }).catch(() => {});
          if (!ok) return sendJSON(res, 401, { error: 'ชื่อผู้ใช้หรือรหัสผ่านไม่ถูกต้อง' });
          const sid = crypto.randomBytes(24).toString('hex');
          sessions.set(sid, { username: user.username, role: user.role });
          setSessionCookie(res, sid);
          return sendJSON(res, 200, { ok: true, username: user.username, role: user.role });
        } catch (e) {
          if (dbLoginLogs) dbLoginLogs.insertOne({ username, time: new Date(), success: false, ip: getClientIp(req) }).catch(() => {});
          return sendJSON(res, 400, { error: 'invalid body', detail: e.message });
        }
      });
      return;
    }

    // ---- API: ออกจากระบบ ----
    if (req.method === 'POST' && url.pathname === '/api/auth/logout') {
      const cookies = parseCookies(req);
      if (cookies.sid) sessions.delete(cookies.sid);
      clearSessionCookie(res);
      return sendJSON(res, 200, { ok: true });
    }

    // ---- API: ข้อมูลผู้ใช้ปัจจุบัน ----
    if (req.method === 'GET' && url.pathname === '/api/auth/me') {
      const session = getSession(req);
      if (!session) return sendJSON(res, 401, { error: 'not logged in' });
      return sendJSON(res, 200, { username: session.username, role: session.role });
    }

    // ---- API: บันทึกการเข้าใช้ระบบ (เฉพาะแอดมิน) ----
    if (req.method === 'GET' && url.pathname === '/api/auth/logs') {
      const session = getSession(req);
      if (!session) return sendJSON(res, 401, { error: 'not logged in' });
      if (session.role !== 'admin') return sendJSON(res, 403, { error: 'forbidden' });
      if (!dbLoginLogs) return sendJSON(res, 500, { error: 'database not connected' });
      try {
        const logs = await dbLoginLogs.find().sort({ time: -1 }).limit(100).toArray();
        return sendJSON(res, 200, logs.map((l) => ({ username: l.username, time: l.time, success: !!l.success, ip: l.ip || '' })));
      } catch (e) {
        return sendJSON(res, 500, { error: 'database error', detail: e.message });
      }
    }

    // ---- API: รายชื่อผู้ใช้ (เฉพาะแอดมิน) ----
    if (req.method === 'GET' && url.pathname === '/api/auth/users') {
      const session = getSession(req);
      if (!session) return sendJSON(res, 401, { error: 'not logged in' });
      if (session.role !== 'admin') return sendJSON(res, 403, { error: 'forbidden' });
      if (!dbUsers) return sendJSON(res, 500, { error: 'database not connected' });
      try {
        const users = await dbUsers.find().sort({ createdAt: 1 }).toArray();
        return sendJSON(res, 200, users.map((u) => ({ username: u.username, role: u.role, createdAt: u.createdAt })));
      } catch (e) {
        return sendJSON(res, 500, { error: 'database error', detail: e.message });
      }
    }

    // ---- API: เพิ่มผู้ใช้ใหม่ (เฉพาะแอดมิน) ----
    if (req.method === 'POST' && url.pathname === '/api/auth/users') {
      const session = getSession(req);
      if (!session) return sendJSON(res, 401, { error: 'not logged in' });
      if (session.role !== 'admin') return sendJSON(res, 403, { error: 'forbidden' });
      if (!dbUsers) return sendJSON(res, 500, { error: 'database not connected' });
      let body = '';
      req.on('data', (chunk) => { body += chunk; });
      req.on('end', async () => {
        try {
          const data = JSON.parse(body);
          const username = String(data.username || '').trim();
          const password = String(data.password || '');
          const role = data.role === 'admin' ? 'admin' : 'user';
          if (!username || !password) return sendJSON(res, 400, { error: 'กรุณากรอกชื่อผู้ใช้และรหัสผ่าน' });
          if (password.length < 6) return sendJSON(res, 400, { error: 'รหัสผ่านต้องมีอย่างน้อย 6 ตัวอักษร' });
          const passwordHash = hashPassword(password);
          await dbUsers.insertOne({ username, passwordHash, role, createdAt: new Date() });
          return sendJSON(res, 200, { ok: true });
        } catch (e) {
          if (e && e.code === 11000) return sendJSON(res, 400, { error: 'มีชื่อผู้ใช้นี้อยู่แล้ว' });
          return sendJSON(res, 400, { error: 'invalid body', detail: e.message });
        }
      });
      return;
    }

    // ---- API: ลบผู้ใช้ (เฉพาะแอดมิน ห้ามลบตัวเอง) ----
    if (req.method === 'DELETE' && url.pathname === '/api/auth/users') {
      const session = getSession(req);
      if (!session) return sendJSON(res, 401, { error: 'not logged in' });
      if (session.role !== 'admin') return sendJSON(res, 403, { error: 'forbidden' });
      if (!dbUsers) return sendJSON(res, 500, { error: 'database not connected' });
      const username = url.searchParams.get('username');
      if (!username) return sendJSON(res, 400, { error: 'missing username' });
      if (username === session.username) return sendJSON(res, 400, { error: 'ไม่สามารถลบบัญชีตัวเองได้' });
      try {
        await dbUsers.deleteOne({ username });
        return sendJSON(res, 200, { ok: true });
      } catch (e) {
        return sendJSON(res, 500, { error: 'database error', detail: e.message });
      }
    }

    // ---- API: อ่านค่า ----
    if (req.method === 'GET' && url.pathname === '/api/storage') {
      if (!getSession(req)) return sendJSON(res, 401, { error: 'not logged in' });
      if (!dbCollection) return sendJSON(res, 500, { error: 'database not connected', detail: 'MONGODB_URI ยังไม่ได้ตั้งค่า หรือเชื่อมต่อไม่สำเร็จ' });
      const key = url.searchParams.get('key');
      if (!key) return sendJSON(res, 400, { error: 'missing key' });
      try {
        const doc = await dbCollection.findOne({ key });
        if (!doc) return sendJSON(res, 404, { error: 'not found' });
        return sendJSON(res, 200, { key: doc.key, value: doc.value, shared: true });
      } catch (e) {
        console.error('[500] GET error:', e.message);
        return sendJSON(res, 500, { error: 'database error', detail: e.message });
      }
    }

    // ---- API: บันทึกค่า ----
    if (req.method === 'POST' && url.pathname === '/api/storage') {
      if (!getSession(req)) return sendJSON(res, 401, { error: 'not logged in' });
      if (!dbCollection) return sendJSON(res, 500, { error: 'database not connected', detail: 'MONGODB_URI ยังไม่ได้ตั้งค่า หรือเชื่อมต่อไม่สำเร็จ' });
      let body = '';
      let tooBig = false;
      req.on('data', (chunk) => {
        body += chunk;
        if (body.length > 8 * 1024 * 1024) { tooBig = true; req.destroy(); }
      });
      req.on('end', async () => {
        if (tooBig) {
          console.error('[400] payload too large');
          return sendJSON(res, 400, { error: 'payload too large' });
        }
        try {
          const data = JSON.parse(body);
          if (!data || !data.key) {
            console.error('[400] missing key. Raw body was:', JSON.stringify(body).slice(0, 300));
            return sendJSON(res, 400, { error: 'missing key', detail: 'parsed but no .key field. rawBody=' + body.slice(0, 200) });
          }
          await dbCollection.updateOne(
            { key: data.key },
            { $set: { key: data.key, value: data.value } },
            { upsert: true }
          );
          return sendJSON(res, 200, { key: data.key, value: data.value, shared: true });
        } catch (e) {
          console.error('[500] POST error:', e.message);
          return sendJSON(res, 500, { error: 'database error', detail: e.message });
        }
      });
      return;
    }

    // ---- หน้าเว็บแอปหลัก (ฝังอยู่ในไฟล์นี้แล้ว ไม่ต้องอ่านจากไฟล์แยก) ----
    if (req.method === 'GET' && (url.pathname === '/' || url.pathname === '/index.html' || url.pathname === '/app.html')) {
      res.writeHead(200, {
        'Content-Type': 'text/html; charset=utf-8',
        'Cache-Control': 'no-store, no-cache, must-revalidate',
        'Pragma': 'no-cache',
      });
      res.end(APP_HTML);
      return;
    }

    res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
    res.end('Not found');
  })().catch((e) => {
    console.error('[UNCAUGHT]', e);
    try { res.writeHead(500); res.end('Internal server error'); } catch (_) {}
  });
});

connectDB().then(() => {
  server.listen(PORT, () => {
    console.log('====================================================');
    console.log(' เซิร์ฟเวอร์พร้อมใช้งานที่ port ' + PORT);
    console.log(' ข้อมูลเก็บอยู่ใน MongoDB Atlas (ไม่ขึ้นกับเครื่อง/instance ที่รัน)');
    console.log('====================================================');
  });
});
